ases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“韩建出任司徒、同平章事”中为受任者。", "biography": null, "status": "draft", "id": "0a022fc7-47b3-5530-98ad-3625fceab9a5"}, {"name": "罗弘信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：罗弘信。", "biography": null, "status": "draft", "id": "da48e163-21a8-54a2-a3a0-cdef2344d96a"}, {"name": "王宗涤", "aliases": ["华洪"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：王宗涤。", "biography": null, "status": "draft", "id": "c4df8006-3248-5260-8c74-b2035f076315"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "顾全武", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：顾全武。", "biography": null, "status": "draft", "id": "82b73ae4-434c-5208-8a2d-89b0830434c2"}, {"name": "台濛", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：台濛。", "biography": null, "status": "draft", "id": "7de43550-c1ce-51b9-bf23-dc637131efc5"}, {"name": "周本", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：周本。", "biography": null, "status": "draft", "id": "88dc9c09-49c3-51ee-b872-381abedabdf2"}, {"name": "秦裴", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261光化元年条所见人物：秦裴。", "biography": null, "status": "draft", "id": "4ab0e3a0-02f3-5d1f-a443-7f286cd5abe2"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "罗绍威", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_